// Build ONE morning digest item from the four sheets read earlier in the chain.
//
// Why the $('Node Name').all() pattern? A Google Sheets "get" node REPLACES the
// items flowing through the chain, so by the time we get here $input only holds
// the LAST read (Orders). n8n lets a Code node reference any earlier node by
// name, so each read is pulled back in full here. Every read sits behind a
// try/catch: the four read nodes are set to "continue on error", so a sheet or
// tab you do not use yet arrives as zero rows and its section is simply
// skipped — a missing tab must never kill the whole digest.
const DAY_MS = 24 * 60 * 60 * 1000;
function rows(name) {
  try { return $(name).all().map(i => i.json); } catch (e) { return []; }
}
let cfg = {};
try { cfg = $('CONFIG — Edit Me').first().json || {}; } catch (e) { cfg = {}; }
const business = cfg.config_business_name || 'Your Business';
const currency = cfg.config_currency || '$';
const now = Date.now();
const startOfDay = (t) => { const d = new Date(t); d.setHours(0, 0, 0, 0); return d.getTime(); };
const todayStart = startOfDay(now);
const dayStr = (t) => { const d = new Date(t); const p = (n) => String(n).padStart(2, '0'); return `${d.getFullYear()}-${p(d.getMonth() + 1)}-${p(d.getDate())}`; };
const todayStr = dayStr(now);
const yesterdayStr = dayStr(now - DAY_MS);
const money = (v) => { const n = parseFloat(String(v == null ? '' : v).replace(/[^0-9.\-]/g, '')); return isNaN(n) ? 0 : n; };
const fmt = (n) => (Math.round(n * 100) / 100).toLocaleString('en-US');

// --- New leads in the last 24 hours (Template 1 `Leads` tab) ---
const leads = rows('Read Leads');
const newLeads = leads.filter(j => {
  const ts = new Date(j['Timestamp']).getTime();
  return !isNaN(ts) && ts > now - DAY_MS && ts <= now;
});

// --- Today's appointments (Template 4 `Appointments` tab) ---
const appointments = rows('Read Appointments');
const todays = appointments
  .filter(j => String(j['Appointment Date'] || '').trim() === todayStr
    && String(j['Status'] || '').trim().toLowerCase() !== 'cancelled')
  .sort((a, b) => String(a['Appointment Time'] || '').localeCompare(String(b['Appointment Time'] || '')));

// --- Overdue invoices (Template 6 `Invoices` tab) ---
// Overdue = not Paid (Cancelled / Written off are also left out — they are not
// money owed) and the Due Date is before today.
const invoices = rows('Read Invoices');
const overdue = invoices.filter(j => {
  const status = String(j['Status'] || '').trim().toLowerCase();
  if (status === 'paid' || status === 'cancelled' || status === 'written off') return false;
  const due = new Date(j['Due Date']).getTime();
  return !isNaN(due) && startOfDay(due) < todayStart;
});
const overdueTotal = overdue.reduce((s, j) => s + money(j['Amount']), 0);

// --- Yesterday's orders (Template 9 `Orders` tab) ---
// Revenue is summed PER CURRENCY exactly as typed in the sheet — no conversion.
const orders = rows('Read Orders');
const yOrders = orders.filter(j => {
  const raw = String(j['Timestamp'] || '').trim();
  const ts = new Date(raw).getTime();
  if (!isNaN(ts)) return dayStr(ts) === yesterdayStr;
  return raw.slice(0, 10) === yesterdayStr;
});
const revenueByCurrency = {};
for (const j of yOrders) {
  const cur = String(j['Currency'] || currency).trim() || currency;
  revenueByCurrency[cur] = (revenueByCurrency[cur] || 0) + money(j['Total']);
}
const revenueText = Object.keys(revenueByCurrency).length
  ? Object.entries(revenueByCurrency).map(([c, v]) => `${c}${fmt(v)}`).join(' + ')
  : `${currency}0`;

// --- Assemble the plain-text digest ---
const lines = [];
lines.push(`Daily Business Digest — ${business}`);
lines.push(todayStr);
lines.push('');
lines.push(`🆕 NEW LEADS (last 24 hours): ${newLeads.length}`);
if (newLeads.length) {
  for (const j of newLeads) lines.push(`- ${j['Name'] || 'Unnamed lead'} — ${j['Interest'] || 'General enquiry'}${j['Company'] ? ` (${j['Company']})` : ''}`);
} else {
  lines.push('All quiet — no new leads in the last 24 hours.');
}
lines.push('');
lines.push(`📅 TODAY'S APPOINTMENTS: ${todays.length}`);
if (todays.length) {
  for (const j of todays) lines.push(`- ${j['Appointment Time'] || 'Time TBC'} — ${j['Client Name'] || 'Client'}${j['Service'] ? ` (${j['Service']})` : ''}`);
} else {
  lines.push('All quiet — no appointments in the diary today.');
}
lines.push('');
lines.push(`⚠️ OVERDUE INVOICES: ${overdue.length} — ${currency}${fmt(overdueTotal)} outstanding`);
if (overdue.length) {
  for (const j of overdue) lines.push(`- ${j['Invoice Number'] || 'Invoice'} — ${j['Client Name'] || 'Client'} — ${currency}${fmt(money(j['Amount']))} (due ${j['Due Date']})`);
} else {
  lines.push('All quiet — no overdue invoices. Everyone has paid.');
}
lines.push('');
lines.push(`🛒 YESTERDAY'S ORDERS: ${yOrders.length} — ${revenueText}`);
if (yOrders.length) {
  for (const j of yOrders) lines.push(`- #${j['Order ID'] || '?'} — ${j['Customer'] || 'Customer'} — ${String(j['Currency'] || currency)}${fmt(money(j['Total']))}`);
} else {
  lines.push('All quiet — no orders yesterday.');
}
lines.push('');
lines.push('Figures come straight from your sheets — if a section looks wrong, check the sheet first.');

const hasUrgent = overdue.length > 0 || todays.length > 0;
return [{ json: {
  digest_text: lines.join('\n'),
  digest_date: todayStr,
  has_urgent: hasUrgent,
  new_leads_count: newLeads.length,
  appointments_today: todays.length,
  overdue_count: overdue.length,
  overdue_total: Math.round(overdueTotal * 100) / 100,
  orders_yesterday: yOrders.length,
} }];
